import { afterEach, describe, expect, it, vi } from 'vitest'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { render, screen, waitFor } from '@testing-library/react'
import { createMemoryRouter, RouterProvider } from 'react-router'
import { mockJsonResponse } from '../../lib/api'
import { VaultLayout } from './VaultLayout'

function renderLayout() {
  const queryClient = new QueryClient({ defaultOptions: { queries: { retry: false } } })
  const router = createMemoryRouter(
    [
      {
        path: '/vaults/:vaultId',
        element: <VaultLayout />,
        children: [{ index: true, element: <div>Empty state</div> }],
      },
    ],
    { initialEntries: ['/vaults/v1'] },
  )
  render(
    <QueryClientProvider client={queryClient}>
      <RouterProvider router={router} />
    </QueryClientProvider>,
  )
}

describe('VaultLayout', () => {
  afterEach(() => {
    vi.unstubAllGlobals()
  })

  it('renders the file tree in the sidebar and the outlet content', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockImplementation((url: string) => {
        if (url === '/api/vaults') {
          return Promise.resolve(
            mockJsonResponse(200, [{ id: 'v1', name: 'Engineering', ownerId: 'u1', mergeable: true, access: 'owner' }]),
          )
        }
        return Promise.resolve(
          mockJsonResponse(200, {
            people: [
              { id: 'n1', path: 'people/jane', type: 'people', name: 'jane', frontmatter: {}, updatedAt: '2026-01-01' },
            ],
          }),
        )
      }),
    )

    renderLayout()

    await waitFor(() => expect(screen.getByRole('link', { name: 'jane' })).toBeInTheDocument())
    expect(screen.getByText('Empty state')).toBeInTheDocument()
    expect(screen.getByRole('link', { name: '← Vaults' })).toHaveAttribute('href', '/')
  })
})

import { Link, Outlet, useParams } from 'react-router'
import { useVaults } from '../../hooks/useVaults.js'
import { useVaultTree } from '../../hooks/useVaultTree.js'
import { FileTree } from '../../components/vault/FileTree.js'

export function VaultLayout() {
  const { vaultId } = useParams<{ vaultId: string }>()
  const vaults = useVaults()
  const tree = useVaultTree(vaultId!)
  const vault = vaults.data?.find((v) => v.id === vaultId)

  return (
    <div className="flex min-h-screen">
      <aside className="w-[220px] shrink-0 border-r border-border bg-secondary p-4">
        <Link to="/" className="mb-4 block text-sm text-muted-foreground underline">
          ← Vaults
        </Link>
        {tree.data && <FileTree vaultId={vaultId!} tree={tree.data} />}
      </aside>
      <div className="flex-1">
        <Outlet context={vault} />
      </div>
    </div>
  )
}

import { useState } from 'react'
import type { FormEvent } from 'react'
import { Input } from '../ui/input'
import { Label } from '../ui/label'
import { Button } from '../ui/button'
import { FormError } from '../FormError'
import { useCreateNote } from '../../hooks/useCreateNote'
import type { CreateNoteResult } from '../../api/notes'

const SLUG = /^[a-z0-9][a-z0-9-]*$/

interface NewNoteFormProps {
  vaultId: string
  existingTypes: string[]
  onCreated: (note: CreateNoteResult) => void
}

export function NewNoteForm({ vaultId, existingTypes, onCreated }: NewNoteFormProps) {
  const [type, setType] = useState('')
  const [name, setName] = useState('')
  const [error, setError] = useState<string | null>(null)
  const createNote = useCreateNote(vaultId)

  function handleSubmit(e: FormEvent) {
    e.preventDefault()
    if (!SLUG.test(type)) {
      setError('Type must be lowercase letters, numbers, and hyphens.')
      return
    }
    if (!SLUG.test(name)) {
      setError('Name must be lowercase letters, numbers, and hyphens.')
      return
    }
    setError(null)
    createNote.mutate(
      { type, name },
      {
        onSuccess: (note) => onCreated(note),
        onError: (err) => setError(err.message || 'Could not create the note.'),
      },
    )
  }

  return (
    <form onSubmit={handleSubmit} className="mb-4 flex flex-col gap-2">
      <Label htmlFor="nn-type">Type</Label>
      <Input
        id="nn-type"
        list="nn-types"
        value={type}
        onChange={(e) => setType(e.target.value)}
        placeholder="e.g. people"
      />
      <datalist id="nn-types">
        {existingTypes.map((t) => (
          <option key={t} value={t} />
        ))}
      </datalist>
      <Label htmlFor="nn-name">Name</Label>
      <Input
        id="nn-name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        placeholder="e.g. jane-doe"
      />
      <FormError message={error} />
      <Button type="submit" disabled={createNote.isPending}>
        {createNote.isPending ? 'Creating…' : 'Create note'}
      </Button>
    </form>
  )
}

