import { apiFetch } from '../lib/api.js'

export type VaultAccess = 'read' | 'edit' | 'owner'

export interface Vault {
  id: string
  name: string
  ownerId: string
  mergeable: boolean
  access: VaultAccess
}

export function listVaults(): Promise<Vault[]> {
  return apiFetch('/vaults')
}

export function getVaultAccess(vaultId: string): Promise<{ access: VaultAccess }> {
  return apiFetch(`/vaults/${vaultId}/access`)
}

/** Editing is allowed only for edit/owner access; unknown access is not. */
export function canEdit(access: VaultAccess | undefined): boolean {
  return access === 'edit' || access === 'owner'
}

import { useQuery } from '@tanstack/react-query'
import { getVaultTree } from '../api/notes.js'
import type { ApiError } from '../lib/api.js'
import type { VaultTree } from '../api/notes.js'

export function useVaultTree(vaultId: string) {
  return useQuery<VaultTree, ApiError>({
    queryKey: ['vault-tree', vaultId],
    queryFn: () => getVaultTree(vaultId),
  })
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import { createNote } from '../api/notes.js'
import type { ApiError } from '../lib/api.js'
import type { CreateNoteInput, CreateNoteResult } from '../api/notes.js'

export function useCreateNote(vaultId: string) {
  const queryClient = useQueryClient()
  return useMutation<CreateNoteResult, ApiError, CreateNoteInput>({
    mutationFn: (input) => createNote(vaultId, input),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ['vault-tree', vaultId] })
    },
  })
}

import { useQuery } from '@tanstack/react-query'
import { listVaults } from '../api/vaults.js'
import type { ApiError } from '../lib/api.js'
import type { Vault } from '../api/vaults.js'

export const VAULTS_QUERY_KEY = ['vaults'] as const

export function useVaults() {
  return useQuery<Vault[], ApiError>({
    queryKey: VAULTS_QUERY_KEY,
    queryFn: listVaults,
  })
}

export class ApiError extends Error {
  status: number
  body: unknown

  constructor(status: number, body: unknown) {
    const message =
      typeof body === 'object' && body !== null && 'error' in body && typeof (body as { error: unknown }).error === 'string'
        ? (body as { error: string }).error
        : `Request failed (${status})`
    super(message)
    this.status = status
    this.body = body
  }
}

export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`/api${path}`, {
    ...init,
    credentials: 'include',
    headers: { 'Content-Type': 'application/json', ...init?.headers },
  })
  const body = await res.json().catch(() => undefined)
  if (!res.ok) throw new ApiError(res.status, body)
  return body as T
}

/** Test-only helper: builds a real Response for stubbed fetch calls. */
export function mockJsonResponse(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'Content-Type': 'application/json' },
  })
}

